255	    @Override
256	    @Transactional
257	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
258	        rejectWhenDailyLimitReached(owner);
259	        rejectWhenCityAtCapacity(owner);
260	        List<Owner> householdMembers = assignHousehold(owner, sharesHousehold);
261	        rejectWhenDuplicateIdentity(owner);
262	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
263	        if (owner.getCustomerCode() == null) {
264	            owner.setCustomerCode(nextCustomerCode(owner));
265	        }
266	        if (owner.getNamesakeCount() == null) {
267	            owner.setNamesakeCount(countNamesakes(owner));
268	        }
269	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
270	        ownerRepository.save(owner);
271	    }
272	
273	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
274	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
275	
276	    /**
277	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
278	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
279	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
280	     * today by the controller, determines which day is counted — the same accumulation path as the
281	     * daily-limit rule.
282	     */
283	    private boolean exceedsBulkSignupThreshold(Owner owner) {
284	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
285	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
286	    }
287	
288	    /**
289	     * Count the existing owners that already share this owner's first name and last name,
290	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
291	     * before the owner is persisted, so it reflects the owners present at creation time.
292	     */
293	    private int countNamesakes(Owner owner) {
294	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
295	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
296	        return (int) ownerRepository.findAll().stream()
297	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
298	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
299	            .count();
300	    }
301	
302	    /**
303	     * Reconcile the owner's household and return its existing members. Owners are in the same
304	     * household when their last name and address match (compared case-insensitively with collapsed
305	     * whitespace). When another owner already lives there and {@code sharesHousehold} is set, the
306	     * new owner and every existing member are given the same stable shared {@code householdId} so
307	     * they form one household; without the opt-in the owner is treated as living alone (no shared
308	     * identifier). Duplicate detection no longer happens here: it is consolidated into the derived
309	     * {@code identityKey} (see {@link #rejectWhenDuplicateIdentity(Owner)}). The returned list is the
310	     * existing members that make up this owner's household (empty when the owner lives alone), so
311	     * callers can derive the household size after this create.
312	     */
313	    private List<Owner> assignHousehold(Owner owner, boolean sharesHousehold) {
314	        if (!sharesHousehold) {
315	            return List.of();
316	        }
317	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
318	        String address = AddressNormalizer.canonical(owner.getAddress());
319	        List<Owner> householdMembers = ownerRepository.findAll().stream()
320	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
321	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
322	            .toList();
323	        if (householdMembers.isEmpty()) {
324	            return householdMembers;
325	        }
326	        String householdId = householdMembers.stream()
327	            .map(Owner::getHouseholdId)
328	            .filter(Objects::nonNull)
329	            .findFirst()
330	            .orElseGet(() -> deriveHouseholdId(lastName, address));
331	        owner.setHouseholdId(householdId);
332	        for (Owner member : householdMembers) {
333	            if (!householdId.equals(member.getHouseholdId())) {
334	                member.setHouseholdId(householdId);
335	                ownerRepository.save(member);
336	            }
337	        }
338	        return householdMembers;
339	    }
340	
341	    /**
342	     * Derive a stable, shared household identifier from the normalized last name and address, so
343	     * every owner in the same household deterministically maps to the same value.
344	     */
345	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
346	        String key = normalizedLastName + "\n" + normalizedAddress;
347	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
348	    }
349	
350	    /**
351	     * Reject the create when the owner's derived {@code identityKey} exactly matches that of an
352	     * existing owner. The key —
353	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} — is the single value
354	     * into which the former separate telephone, e-mail and household duplicate checks are
355	     * consolidated: only an exact whole-key match is a duplicate, so two members of the same
356	     * household with different telephones (hence different keys) are both allowed. Evaluated after
357	     * the household has been reconciled (so the {@code householdId} segment is settled) and before
358	     * the owner is persisted, so it reflects the owners present at creation time.
359	     */
360	    private void rejectWhenDuplicateIdentity(Owner owner) {
361	        String identityKey = IdentityKeyNormalizer.derive(owner);
362	        boolean duplicate = ownerRepository.findAll().stream()
363	            .anyMatch(existing -> identityKey.equals(IdentityKeyNormalizer.derive(existing)));
364	        if (duplicate) {
365	            throw new DuplicateIdentityException(
366	                "an owner with identity key " + identityKey + " already exists");
367	        }
368	    }
369	
370	    /** Maximum number of owners that may be created on any single day (by registration date). */
371	    private static final long DAILY_OWNER_LIMIT = 100L;
372	
373	    /**
374	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
375	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
376	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
377	     * to today by the controller, determines which day the limit is checked against.
378	     */
379	    private void rejectWhenDailyLimitReached(Owner owner) {
380	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
381	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
382	            throw new DailyOwnerLimitExceededException(
383	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
384	        }
385	    }
386	
387	    /**
388	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
389	     * before the owner is persisted, so it reflects the owners present at creation time.
390	     */
391	    private long countOwnersRegisteredOn(LocalDate day) {
392	        return ownerRepository.findAll().stream()
393	            .filter(existing -> day.equals(existing.getRegistrationDate()))
394	            .count();
395	    }
396	
397	    /** Maximum number of owners allowed to live in any single city. */
398	    private static final long CITY_CAPACITY = 50L;
399	
400	    /**
401	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
402	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
403	     * is persisted, so it reflects the owners present at creation time.
404	     */
405	    private void rejectWhenCityAtCapacity(Owner owner) {
406	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
407	            throw new CityCapacityExceededException(
408	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
409	        }
410	    }
411	
412	    /**
413	     * Count the existing owners that already live in this owner's city, compared
414	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
415	     * owner is persisted, so it reflects the owners present at creation time.
416	     */
417	    private long countOwnersInCity(Owner owner) {
418	        String city = IdentityNormalizer.normalize(owner.getCity());
419	        return ownerRepository.findAll().stream()
420	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
421	            .count();
422	    }
423	
424	    /**
425	     * Builds the customer code {@code '<CITY3>-<LAST3>-<NNNN>'}: the upper-cased first
426	     * three letters of the owner's {@code city}, a hyphen, the upper-cased first three
427	     * letters of {@code lastName}, a hyphen, and a 4-digit zero-padded per-city sequence
428	     * equal to one more than the number of owners already in that city (compared
429	     * case-insensitively with collapsed whitespace).
430	     */
431	    private String nextCustomerCode(Owner owner) {
432	        String city3 = prefix3(owner.getCity());
433	        String last3 = prefix3(owner.getLastName());
434	        long sequence = countOwnersInCity(owner) + 1L;
435	        return String.format("%s-%s-%04d", city3, last3, sequence);
436	    }
437	
438	    /**
439	     * Returns the upper-cased first three letters of {@code value}, or fewer when the value
440	     * is shorter; a {@code null} value yields an empty string.
441	     */
442	    private static String prefix3(String value) {
443	        String name = value == null ? "" : value;
444	        return name.substring(0, Math.min(3, name.length())).toUpperCase();
445	    }
446	
447	    @Override
448	    @Transactional(readOnly = true)
449	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
450	        return ownerRepository.findByLastName(lastName);
451	    }
452	
453	    @Override
454	    @Transactional(readOnly = true)
455	    public Collection<Visit> findVisitsByPetId(int petId) {
456	        return visitRepository.findByPetId(petId);
457	    }
458	
459	    @Override
460	    @Transactional(readOnly = true)
461	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
462	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
463	    }
464	
465	    private <T> T findEntityById(Supplier<T> supplier) {
466	        try {
467	            return supplier.get();
468	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
469	            // Just ignore not found exceptions for Jdbc/Jpa realization
470	            return null;
471	        }
472	    }
473	
474	}
