29	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    Owner toOwner(OwnerDto ownerDto);
35	
36	    /**
37	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
38	     */
39	    default String displayName(Owner owner) {
40	        if (owner == null) {
41	            return null;
42	        }
43	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
44	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
45	        return lastName + ", " + firstName;
46	    }
47	
48	    /**
49	     * Returns the upper-cased first letters of firstName and lastName,
50	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
51	     */
52	    default String initials(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        StringBuilder sb = new StringBuilder();
57	        String firstName = owner.getFirstName();
58	        String lastName = owner.getLastName();
59	        if (firstName != null && !firstName.isEmpty()) {
60	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
61	        }
62	        if (lastName != null && !lastName.isEmpty()) {
63	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
64	        }
65	        return sb.toString();
66	    }
67	
68	    /**
69	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
70	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
71	     * Returns {@code null} unless both the customer code and registration date are present.
72	     */
73	    default String membershipNumber(Owner owner) {
74	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
75	            return null;
76	        }
77	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
78	        return owner.getCustomerCode() + "-M" + yy;
79	    }
80	
81	    /**
82	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
83	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
84	     */
85	    default Integer checkDigit(Owner owner) {
86	        if (owner == null || owner.getCustomerCode() == null) {
87	            return null;
88	        }
89	        String code = owner.getCustomerCode();
90	        int sum = 0;
91	        boolean dbl = true;
92	        for (int i = code.length() - 1; i >= 0; i--) {
93	            char c = code.charAt(i);
94	            if (c < '0' || c > '9') {
95	                continue;
96	            }
97	            int d = c - '0';
98	            if (dbl) {
99	                d *= 2;
100	                if (d > 9) {
101	                    d -= 9;
102	                }
103	            }
104	            sum += d;
105	            dbl = !dbl;
106	        }
107	        return (10 - (sum % 10)) % 10;
108	    }
109	
110	    /**
111	     * Returns the owner's numeric membership level. Starts at {@code 1}; adds {@code 1} when an
112	     * email address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is
113	     * 0); capped at {@code 3} (level 4 is reserved for tenure).
114	     */
115	    default Integer membershipLevel(Owner owner) {
116	        if (owner == null) {
117	            return null;
118	        }
119	        int level = 1;
120	        String email = owner.getEmail();
121	        if (email != null && !email.isEmpty()) {
122	            level++;
123	        }
124	        Integer namesakeCount = owner.getNamesakeCount();
125	        if (namesakeCount != null && namesakeCount == 0) {
126	            level++;
127	        }
128	        return Math.min(level, 3);
129	    }
130	
131	    /** Fixed city-to-region table used to derive an owner's locality. */
132	    Map<String, String> CITY_REGION = Map.of(
133	        "Sydney", "NSW",
134	        "Melbourne", "VIC",
135	        "Brisbane", "QLD");
136	
137	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
138	    Map<String, int[]> REGION_POSTCODES = Map.of(
139	        "NSW", new int[] {2000, 2099},
140	        "VIC", new int[] {3000, 3099},
141	        "QLD", new int[] {4000, 4099});
142	
143	    /**
144	     * Derives the owner's locality (region), preferring the postcode. The postcode range is
145	     * consulted first ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); only
146	     * when the postcode is absent or falls in no known range does it fall back to the fixed
147	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
148	     * Returns {@code "UNKNOWN"} when neither the postcode nor the city yields a region.
149	     */
150	    default String locality(Owner owner) {
151	        if (owner == null) {
152	            return null;
