19	import java.util.Map;
20	
21	/**
22	 * Utility for normalizing telephone numbers into
23	 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form.
24	 *
25	 * <p>Spaces, dashes and brackets are stripped. When the value already carries a
26	 * leading {@code '+'} the country code is kept as supplied; otherwise the country
27	 * code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
28	 * national digits. The result must contain between 8 and 15 digits after the
29	 * {@code '+'}; anything else raises an {@link InvalidTelephoneException} so the
30	 * request is rejected with {@code 400 Bad Request}. For example {@code '0412 345 678'}
31	 * becomes {@code '+61412345678'}.
32	 *
33	 * <p>In addition, for recognized country codes the national number (the digits after
34	 * the country code) must be exactly the length that country uses: {@code '+61'}
35	 * (Australia) requires 9 national digits and {@code '+1'} (NANP) requires 10. A number
36	 * whose national-number length does not match its country code is rejected.
37	 */
38	public final class TelephoneNormalizer {
39	
40	    private static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    private static final int MIN_DIGITS = 8;
43	
44	    private static final int MAX_DIGITS = 15;
45	
46	    /**
47	     * Known country calling codes mapped to the exact number of national digits that
48	     * must follow them in a valid E.164 number. Codes not listed here fall back to the
49	     * generic {@link #MIN_DIGITS}-to-{@link #MAX_DIGITS} bound only.
50	     */
51	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY_CODE = Map.of(
52	        "61", 9,
53	        "1", 10);
54	
55	    private TelephoneNormalizer() {
56	    }
57	
58	    /**
59	     * Normalize the supplied telephone into E.164 form.
60	     *
61	     * @param telephone the raw telephone value (may be {@code null})
62	     * @return the normalized E.164 telephone (a leading {@code '+'} followed by digits)
63	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
64	     */
65	    public static String normalize(String telephone) {
66	        String e164 = toE164(telephone);
67	        if (e164 == null) {
68	            throw new InvalidTelephoneException(
69	                "telephone must be a valid E.164 number (8 to 15 digits after the '+', "
70	                    + "with a national-number length matching its country code: "
71	                    + "'+61' requires 9 national digits, '+1' requires 10)");
72	        }
73	        return e164;
74	    }
75	
76	    /**
77	     * Best-effort conversion of the supplied telephone into E.164 form, returning
78	     * {@code null} instead of throwing when the value cannot form a valid E.164 number.
79	     * Useful for comparing telephones that may already be stored in a non-normalized form.
80	     *
81	     * @param telephone the raw telephone value (may be {@code null})
82	     * @return the E.164 telephone, or {@code null} if it cannot be formed
83	     */
84	    public static String toE164(String telephone) {
85	        if (telephone == null) {
86	            return null;
87	        }
88	        String cleaned = telephone.replaceAll("[\\s\\-()\\[\\]]", "");
89	        String digits;
90	        if (cleaned.startsWith("+")) {
91	            digits = cleaned.substring(1);
92	        }
93	        else {
94	            String national = cleaned;
95	            if (national.startsWith("0")) {
96	                national = national.substring(1);
97	            }
98	            digits = DEFAULT_COUNTRY_CODE + national;
99	        }
100	        if (!digits.matches("\\d+")) {
101	            return null;
102	        }
103	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
104	            return null;
105	        }
106	        if (!hasValidNationalLength(digits)) {
107	            return null;
108	        }
109	        return "+" + digits;
