 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
 * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
 */
private static String regionForPostcode(String postcode) {
